import math

def kl_bits(p, q):
    """D(p || q) in bits; math.inf if some q_i = 0 < p_i."""
    total = 0.0
    for pi, qi in zip(p, q):
        if pi == 0:
            continue
        if qi == 0:
            return math.inf
        total += pi * math.log2(pi / qi)
    return total
